class AuthenticationClient:
    def __init__(self, *, client_wrapper: SyncClientWrapper):
        self._raw_client = RawAuthenticationClient(client_wrapper=client_wrapper)

    @property
    def with_raw_response(self) -> RawAuthenticationClient:
        """
        Retrieves a raw implementation of this client that returns raw responses.

        Returns
        -------
        RawAuthenticationClient
        """
        return self._raw_client

    def telegram_login_start(
        self, *, idempotency_key: Uuid, phone_number: str, request_options: typing.Optional[RequestOptions] = None
    ) -> TelegramLoginStartResponse:
        """
        Begin Telegram authentication and send a login code.

        Parameters
        ----------
        idempotency_key : Uuid
            Stable UUID generated by the caller for safe request retries.

        phone_number : str
            Phone number in E.164 format.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        TelegramLoginStartResponse
            The request has succeeded and a new resource has been created as a result.

        Examples
        --------
        from fern import FernApi

        client = FernApi(
            api_key="YOUR_API_KEY",
            token="YOUR_TOKEN",
        )
        client.authentication.telegram_login_start(
            idempotency_key="Idempotency-Key",
            phone_number="phoneNumber",
        )
        """
        _response = self._raw_client.telegram_login_start(
            idempotency_key=idempotency_key, phone_number=phone_number, request_options=request_options
        )
        return _response.data

